post.description:
Merges one or more PDFs of a requisition into a single PDF. There are two ways to use this endpoint. First to generate a cover sheet for the requisition.
If you would like to receive a polling URL that will follow the job provide the polling option in the query params `polling=true`. If you would like the file emailed to you omit the polling param in the query params.
You can use the following request payload as an example

````json
{
  "files":[
    {"type": "cover_sheet", "id": ""}
  ]
}
````
If you would like to include some attachments, you can use the following request payload as an example

````json
{
  "files": [
    {
      "id": "",
      "type": "cover_sheet"
    },
    {
      "id": 1234,
      "url": "http://example.com/file_1.pdf",
      "type": "prostore_file"
    }
  ]
}
````

x-code-samples.content:
const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/requisitions/%7Brequisition_id%7D/single_pdf_compilers',
  qs: {polling: 'SOME_BOOLEAN_VALUE', project_id: 'SOME_INTEGER_VALUE'},
  headers: {'content-type': 'application/json'},
  body: {files: [{type: 'prostore_file', id: 1234, url: 'https://example.com/foo.pdf'}]},
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/requisitions/%7Brequisition_id%7D/single_pdf_compilers?polling=SOME_BOOLEAN_VALUE&project_id=SOME_INTEGER_VALUE"),
    Content = new StringContent("{\"files\":[{\"type\":\"prostore_file\",\"id\":1234,\"url\":\"https://example.com/foo.pdf\"}]}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
